const now = new Date();
const currentDay = now.getDate();
const currentMonth = now.getMonth();

const monthNames = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December"
];

let startMonthIndex = (currentDay >= 18) ? currentMonth : (currentMonth - 1 + 12) % 12;
let endMonthIndex = (startMonthIndex + 1) % 12;

const activeCycle = `${monthNames[startMonthIndex]}/${monthNames[endMonthIndex]}`;

return [{
  json: {
    activeCycle: activeCycle
  }
}];

const activeCycle = $('get cycle').first().json.activeCycle
const resumeData = $('get resume').all().map(item => item.json)
const currentCycleData = resumeData.find(item => item.MES === activeCycle)

if (!currentCycleData) {
  return [{
    json: {
      mensagem: `⚠️ **Finance Notification**\n\nCould not find the active cycle (**${activeCycle}**) in the 'Resume' sheet.`
    }
  }]
}

const formatBRL = (value) =>
  Number(value).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })

const transactions = $('get finances by month').all().map(item => item.json)

const totals = {};
for (const t of transactions) {
  const cat = t.Categoria || t.CATEGORIA || 'Sem categoria';
  const val = Number(t.Gasto || t.GASTO || 0);
  totals[cat] = (totals[cat] || 0) + val;
}

let sorted = Object.entries(totals).sort((a, b) => b[1] - a[1]);

let breakdownRows;
if (sorted.length > 4) {
  const top4 = sorted.slice(0, 4);
  const rest = sorted.slice(4);
  const outrosTotal = rest.reduce((sum, [, v]) => sum + v, 0);
  breakdownRows = [...top4, ['Outros', outrosTotal]];
} else {
  breakdownRows = sorted;
}

const totalExpanse = Number(currentCycleData["GASTO ATUAL"]);

const barFor = (value) => {
  const pct = totalExpanse > 0 ? Math.round((value / totalExpanse) * 100) : 0;
  const blocks = totalExpanse > 0 ? Math.round((value / totalExpanse) * 10) : 0;
  const bar = '█'.repeat(blocks) + '░'.repeat(10 - blocks);
  return { pct, bar };
};

const breakdownText = breakdownRows.length
  ? breakdownRows.map((row) => {
      const cat = String(row[0]);
      const val = Number(row[1]);
      const { pct, bar } = barFor(val);
      return `${cat.padEnd(14)} ${formatBRL(val).padStart(12)} (${pct}%) ${bar}`;
    }).join('\n')
  : null


let formattedMessage = `📊 **Resumo do Ciclo (${activeCycle}):**
- **Total gasto no mês:** ${formatBRL(currentCycleData["GASTO ATUAL"])}
- **Valor disponível para gastar:** ${formatBRL(currentCycleData["VALOR RESTANTE"])}`;

if (breakdownText) {
  formattedMessage += `\n\n📈 **Gastos por categoria:**\n\`\`\`\n${breakdownText}\n\`\`\``;
}

return [{ json: { mensagem: formattedMessage } }];
